"""Private Lab calendar shell. No member data is included in generated HTML."""
def build_lab(page):
    page('lab', 'Book the Governance Lab', 'Private room reservations and scheduled classes for approved Kapukai Lab members.', '''
<link rel="stylesheet" href="/assets/community/lab.css">
<div class="lab-heading"><div><p class="eyebrow">Kapukai Governance Lab · Member access</p><h1>A place to work.<br>A time to begin.</h1><p class="lede">Book an available room or class seat for this week. Approved Lab members receive immediate confirmation.</p></div><button id="lab-signout" type="button" class="button secondary" hidden>Sign out</button></div>
<p id="lab-status" role="status" aria-live="polite" tabindex="-1"></p>
<section id="lab-entry" class="panel lab-entry"><h2>Sign in with your Kapukai account</h2><p>Use your existing email and password. Kapukai approves Lab access once; available bookings then confirm automatically.</p><form id="lab-login"><label for="lab-email">Email address</label><input id="lab-email" name="email" type="email" autocomplete="username" maxlength="254" required><label for="lab-password">Password</label><input id="lab-password" name="password" type="password" autocomplete="current-password" maxlength="128" required><button type="submit">Sign in</button></form><p class="small">Need an account or help with access? <a href="/community/members/">Visit the member workspace</a> or <a href="mailto:architect@kapukai.org">contact Kapukai</a>.</p></section>
<section id="lab-access" class="notice" hidden><h2>Lab access is by approval</h2><p>Your Kapukai account is signed in. Contact Kapukai to be added to the Lab member list.</p></section>
<div id="lab-workspace" hidden>
<p id="lab-paused" class="notice" hidden>Booking opens after the Lab schedule is set. Existing reservations remain visible below.</p>
<section id="lab-calendar-section" aria-labelledby="lab-calendar-title">
<div class="lab-toolbar"><div><h2 id="lab-calendar-title">This week at the Lab</h2><p id="lab-week-label"></p></div><div class="lab-week-controls"><button id="lab-previous" type="button" class="button secondary" aria-label="Previous week">←</button><button id="lab-today" type="button" class="button secondary">This week</button><button id="lab-next" type="button" class="button secondary" aria-label="Next week">→</button><button id="lab-refresh" type="button" class="button secondary">Refresh</button></div></div>
<div class="lab-room-row"><label for="lab-room">Room</label><select id="lab-room"></select><label for="lab-hours-view">Hours shown</label><select id="lab-hours-view"><option value="daytime">7 a.m.–7 p.m.</option><option value="full">Full day</option></select><span id="lab-zone" class="small"></span></div>
<p class="small">Book this week only: Monday–Sunday, Eastern time. Select a start at :00, :15, :30 or :45, then choose when to finish. Private reservations appear as “Reserved.”</p><div class="lab-legend"><span><i class="available"></i>Available start</span><span><i class="reserved"></i>Reserved</span><span><i class="class"></i>Scheduled class</span></div>
<p id="lab-no-hours" class="notice" hidden>No opening times have been published for this room this week.</p>
<div id="lab-calendar-scroll" class="lab-calendar-scroll" tabindex="0" aria-label="Weekly calendar. Scroll to see all hours."><div id="lab-calendar"></div></div>
</section>
<section id="lab-selection" class="panel" hidden aria-labelledby="lab-selection-title"><h2 id="lab-selection-title" tabindex="-1">Reserve this time</h2><form id="lab-book"><div class="lab-fields"><div><label for="lab-date">Date</label><input id="lab-date" name="date" type="date" required></div><div><label for="lab-start">Start time</label><select id="lab-start" name="start" required></select></div><div><label for="lab-end">End time</label><input id="lab-end" name="end" type="time" step="60" required></div><div><label for="lab-participants">Participants</label><input id="lab-participants" name="participants" type="number" min="1" max="6" value="1" required></div><div><label for="lab-mode">Use of the room</label><select id="lab-mode" name="mode"><option value="room">Book the entire room</option><option value="organize">Host an organizing session</option></select></div></div><p id="lab-book-note" class="small">An organizing session reserves the entire room. Invite your group directly; this does not publish an open invitation.</p><div class="lab-actions"><button id="lab-book-submit" type="submit">Confirm reservation</button><button id="lab-selection-close" type="button" class="button secondary">Close</button></div></form></section>
</div>
<section id="lab-mine-section" hidden><h2>My reservations</h2><p class="small">This is your reservation record, even if an email is delayed. Times are shown in the Lab’s time zone.</p><div id="lab-mine"></div></section>
<section id="lab-operator" hidden aria-labelledby="lab-operator-title"><h2 id="lab-operator-title">Manage the Lab</h2><p>Approve people once. Available reservations in the current week then confirm automatically.</p><div id="lab-operator-forms" class="lab-operator-grid"></div></section>
<p class="lab-privacy small">The calendar shares room availability with approved Lab members. It does not share private booking subjects, participant identities or entry codes. Confirmation emails go to the person booking and Kapukai. Please keep case records out of booking details.</p>
''', 'lab.js')
